"""Supporting Information tables for manuscript v11, generated from result files only. Writes manuscript/si_tables_v11.md."""
import os, sys, json, pandas as pd, numpy as np
H = os.path.dirname(os.path.abspath(__file__)); R = os.path.join(H, "results"); OUT = os.path.join(H, "..", "..", "..", "..", "manuscript", "si_tables_v11.md")
sys.path.insert(0, os.path.join(H, "..", "..", "..", "tool")); from fprcal import plan
import atlas_v5 as A5
f = lambda d: d.to_markdown(index=False, floatfmt=".3f")
meta = pd.read_csv(os.path.join(H, "..", "..", "..", "tool", "fprcal", "data", "atlas_perpop_strict_v5.csv"))
T = pd.read_csv(os.path.join(R, "tests_v5.csv")); T["training cohorts"] = T.test.map(lambda t: ", ".join(A5.TESTS[t][1]))
o = ["# Supporting Information — tables (v11; generated by code/experiments/atlas/v5/make_si_v11.py)\n",
     "## Table S1a. The 14 disease tests (28 classifiers): training data, out-of-fold AUROC and training operating point\n",
     f(T[["test", "model", "cohorts", "n_cases", "n_controls", "auroc", "train_fpr", "train_sens", "training cohorts"]]) + "\n"]
pp = meta.groupby("study").agg(country=("country", "first"), non_westernized=("non_westernized", "first"), n_max=("n", "max"), tests_scored=("test", "nunique")).reset_index()
o += ["## Table S1b. The 36 strict healthy populations (n = people scored; a test skips its own training cohorts)\n", f(pp) + "\n"]
for s in ["strict", "full"]:
    h = pd.read_csv(os.path.join(R, f"v5_het_{s}.csv"))
    o += [f"## Table S2{'a' if s == 'strict' else 'b'}. Between-population heterogeneity, {s} set (DerSimonian–Laird on empirical logit FPR; oob = share of populations outside 0.05–0.15)\n",
          f(h[["test", "model", "populations", "people", "pooled", "tau", "I2", "Q_p", "pi_lo", "pi_hi", "oob", "fpr_min", "fpr_max", "auroc"]]) + "\n"]
S = json.load(open(os.path.join(R, "v5_summary.json"))); N = json.load(open(os.path.join(R, "numbers_v11.json")))
vd = pd.DataFrame([dict(set=k.split("_")[1], model=k.split("_")[2], **{a: S[k][a] for a in ["var_test", "var_pop", "var_resid", "test_share", "pop_share", "units", "populations"]}) for k in S if k.startswith("H2_")])
vd["pair_share"] = 1 - vd.test_share - vd.pop_share
o += ["## Table S3. Crossed random-effects decomposition of logit FPR (protocol_v5 H2; residual = test–population pair + binomial noise)\n", f(vd) + "\n"]
tt = pd.read_csv(os.path.join(R, "v5_top_taxa.csv"))
o += ["## Table S4. Taxon decomposition (LASSO, strict set): top-10 positive contributors to the score shift of each test's most over-flagged population (protocol_v5 H3)\n",
      f(tt[["test", "study", "fpr", "rank", "taxon", "w", "dz", "contrib"]]) + "\n"]
u = pd.read_csv(os.path.join(R, "v5_h4_units.csv")); pt = u.groupby(["test", "model"]).agg(evaluations=("pop", "size"), populations=("pop", "nunique"), training_cutoff=("src", "mean"), burn_in=("burn", "mean")).reset_index()
o += ["## Table S5. Within-site burn-in (N = 100; accession order or covariate halves) vs training cut-off: mean |FPR − 0.10| per classifier (protocol_v5 H4)\n", f(pt) + "\n"]
rp = json.load(open(os.path.join(R, "replication_v5.json"))); ex = json.load(open(os.path.join(R, "explore_v5.json")))
rows = [dict(test=t, rho_explore=ex["dist_lasso"]["per_test"][t]["rho_fpr"], replication_pops=v["pops"], rho_replication=v["rho"]) for t, v in rp["H5_lasso"]["per_test"].items()]
o += ["## Table S6. Exploratory distance–FPR correlation (strict set) and its pre-registered replication (Addendum A, LASSO)\n", f(pd.DataFrame(rows)) + "\n",
      "Summary: " + "; ".join(f"{k}: {rp[k]['verdict']}" for k in ["H5_lasso", "H6_lasso", "H5_rf", "H6_rf"]) + "\n"]
o += ["## Table S7. Power of local verification (post hoc; observed FPR treated as true; exact one-sided binomial test of FPR ≤ 0.15 at 0.05)\n", f(pd.read_csv(os.path.join(R, "verify_power_v5.csv"))) + "\n",
      "## Table S8. Burn-in planning table (exact Beta law; alpha = 0.10, pi_max = 0; PAC delta = 0.05). Output of `fprcal plan`\n", f(pd.DataFrame(plan())) + "\n",
      "## Tables S9–S23. Earlier analyses of the CRC, IBD and T2D tests (fixes that failed, cross-site burn-in, control augmentation, contaminated burn-in, Holm correction, duplicates)\n",
      "These are Tables S1–S15 of the previous version, unchanged, in manuscript/si_tables_v4.md (generated by code/experiments/atlas/v4/make_si_v4.py), renumbered S9–S23 in the same order.\n"]
open(OUT, "w").write("\n".join(o)); print("written", OUT)
